// Some portions generated by Claude
/**
 * The Graph page's path from a query answer to a drawn, laid-out graph, without the browser: the answer becomes the
 * graph model, the canvas scope, the layout the worker computes, the positions written back, and a frame of the
 * large-graph canvas (its WebGL upload and draw calls, and its 2D overlay of labels and details).
 */
import { CanvasGraph } from "../../../../main/frontend/graph-explorer/graph-canvas-controller.ts";
import { canvasGraph } from "../../../../main/frontend/graph-explorer/graph-canvas-scope.ts";
import { fitBoxes } from "../../../../main/frontend/graph-explorer/graph-geometry.ts";
import { computeGraphLayout } from "../../../../main/frontend/graph-explorer/graph-layout-engine.ts";
import { applyGraphPositions } from "../../../../main/frontend/graph-explorer/graph-model.ts";
import { mergeTriples, withLoadedTypes } from "../../../../main/frontend/graph-explorer/graph-operations.ts";
import { bindingsToTriples } from "../../../../main/frontend/graph-explorer/graph-terms.ts";
import { parseSparqlResponse } from "../../../../main/frontend/graph-explorer/rdf-results.ts";

/** A WebGL context that records what the renderer asks for (the GPU work itself is the browser's). */
function recordingWebGl(stats) {
  let id = 0;
  const constants = {
    ARRAY_BUFFER: 1, ELEMENT_ARRAY_BUFFER: 2, UNSIGNED_SHORT: 3, UNSIGNED_INT: 4, LINES: 5, POINTS: 6,
    COMPILE_STATUS: 7, LINK_STATUS: 8, FLOAT: 9, STATIC_DRAW: 10, DYNAMIC_DRAW: 11, BLEND: 12, SRC_ALPHA: 13,
    ONE_MINUS_SRC_ALPHA: 14, COLOR_BUFFER_BIT: 15,
  };
  return new Proxy({
    canvas: { width: 1280, height: 780 },
    ...constants,
    getExtension: () => ({}),
    getShaderParameter: () => true,
    getProgramParameter: () => true,
    getAttribLocation: () => 0,
    getUniformLocation: () => ({}),
    bufferData: (_target, data) => { stats.bufferBytes += data?.byteLength ?? 0; },
    bufferSubData: (_target, _offset, data) => { stats.bufferBytes += data?.byteLength ?? 0; },
    drawElements: (_mode, count) => { stats.drawnElements += count; },
    drawArrays: (_mode, _first, count) => { stats.drawnElements += count; },
  }, {
    get(target, key) {
      if (key in target) return target[key];
      if (String(key).startsWith("create")) return () => ({ id: ++id });
      return () => {};
    },
  });
}

/** A 2D context that counts its drawing calls and measures text roughly (7 px per character). */
function recording2d(stats) {
  const context = {
    fillStyle: "#000", strokeStyle: "#000", lineWidth: 1, font: "", textBaseline: "", textAlign: "", globalAlpha: 1,
    measureText: (text) => ({ width: text.length * 7 }),
  };
  return new Proxy(context, {
    get(target, key) {
      if (key in target) return target[key];
      return () => { stats.canvasCalls++; };
    },
    set(target, key, value) {
      target[key] = value;
      return true;
    },
  });
}

function canvasElement(context) {
  return {
    width: 0,
    height: 0,
    dataset: {},
    getContext: (kind) => context(kind),
    getBoundingClientRect: () => ({ left: 0, top: 0, width: 1280, height: 780, right: 1280, bottom: 780 }),
    addEventListener() {},
    removeEventListener() {},
  };
}

/** The browser globals the canvas renderer reads; frames run when `flushFrames` is called. */
function installBrowser() {
  const frames = [];
  const saved = {};
  const globals = {
    window: { matchMedia: () => ({ matches: false }), devicePixelRatio: 1 },
    requestAnimationFrame: (callback) => frames.push(callback),
    cancelAnimationFrame: () => {},
    getComputedStyle: () => ({ getPropertyValue: () => "" }),
    ResizeObserver: class {
      constructor(callback) { this.callback = callback; }
      observe() { this.callback([]); }
      disconnect() {}
    },
  };
  for (const [name, value] of Object.entries(globals)) {
    saved[name] = Object.getOwnPropertyDescriptor(globalThis, name);
    Object.defineProperty(globalThis, name, { value, configurable: true, writable: true });
  }
  return {
    flushFrames() {
      let count = 0;
      while (frames.length) {
        frames.shift()();
        count++;
      }
      return count;
    },
    restore() {
      for (const [name, descriptor] of Object.entries(saved)) {
        if (descriptor) Object.defineProperty(globalThis, name, descriptor);
        else delete globalThis[name];
      }
    },
  };
}

/** Draws `graph` once on the large-graph canvas, fitted to the view, as the explorer does after a layout. */
export function drawFrame(graph) {
  const stats = { bufferBytes: 0, drawnElements: 0, canvasCalls: 0, renderer: "" };
  const browser = installBrowser();
  try {
    const transform = fitBoxes(graph.nodes.map((node) => ({ x: node.x ?? 0, y: node.y ?? 0, width: 220, height: 50 })));
    const props = {
      graph, transform, selected: new Set(), focused: null, showLabels: true, groups: [], arranging: false,
      zoomOnScroll: true, onSelect() {}, onMenu() {}, onPositions() {}, onTransform() {}, onInterrupt() {},
    };
    const overlay2d = recording2d(stats);
    const base = canvasElement((kind) => (kind === "webgl" ? recordingWebGl(stats) : null));
    const overlay = canvasElement((kind) => (kind === "2d" ? overlay2d : null));
    const view = new CanvasGraph(base, overlay, () => props);
    browser.flushFrames();
    stats.renderer = overlay.dataset.renderer;
    stats.frames = Number(overlay.dataset.frames ?? 0);
    view.dispose();
    return stats;
  } finally {
    browser.restore();
  }
}

/**
 * Runs the whole path for a SPARQL Results JSON answer and times each step in milliseconds. `total` is the time from
 * the answer to the drawn frame of the laid-out graph.
 */
export async function answerToFrame(results) {
  const times = {};
  let started = performance.now();
  const mark = (name) => {
    const now = performance.now();
    times[name] = now - started;
    started = now;
  };
  const text = JSON.stringify(results);
  const begin = performance.now();
  started = begin;
  const rows = parseSparqlResponse(text, { repositoryReferences: true }).results.bindings;
  mark("parse");
  const graph = withLoadedTypes(mergeTriples({ nodes: [], edges: [], revision: 0 }, bindingsToTriples(rows), true, "batch"));
  const drawn = canvasGraph(graph, false);
  mark("model");
  const layout = await computeGraphLayout(drawn, { aspectRatio: 1280 / 780 });
  mark("layout");
  const placed = canvasGraph(applyGraphPositions(graph, layout.positions), false);
  mark("positions");
  const frame = drawFrame(placed);
  mark("render");
  times.total = performance.now() - begin;
  return { times, graph, drawn: placed, layout, frame };
}
